mapper.select:
SELECT tae.artifact_id, tae.bool_scheduling, SUM(tae.quantity) AS task_volume, ta.project_id, ta.monomer_id, ta.area_id, cp.short_name AS project_name, pm.name AS monomer_name, pa.name AS area_name, ta.name, ta.serial_number, ta.specification, ta.length, ta.material FROM tech_artifact_ext tae LEFT JOIN tech_artifact ta ON ta.bool_delete_enum = FALSE AND ta.id = tae.artifact_id LEFT JOIN contract_project cp ON cp.bool_delete_enum = FALSE AND cp.id = ta.project_id LEFT JOIN plan_monomer pm ON pm.bool_delete_enum = FALSE AND pm.id = ta.monomer_id LEFT JOIN plan_area pa ON pa.bool_delete_enum = FALSE AND pa.id = ta.area_id WHERE tae.bool_delete_enum = FALSE AND tae.bool_beforehand_scheduling = TRUE
AND tae.project_id = #{projectId}
AND tae.production_way = #{productionWay}
AND tae.workshop_id = #{workshopId}
AND tae.bool_scheduling = #{boolScheduling}
GROUP BY tae.artifact_id, tae.bool_scheduling

SELECT ta.id AS artifact_id, ta.project_id, ta.monomer_id, ta.area_id, ta.name, ta.serial_number, ta.specification, ta.length, ta.material, (ta.quantity - IFNULL(t1.quantity, 0)) AS quantity, ta.net_weight, ((ta.quantity - IFNULL(t1.quantity, 0)) * ta.net_weight) AS total_net_weight, pa.name AS area_name FROM tech_artifact ta LEFT JOIN ( SELECT artifact_id, SUM(quantity) AS quantity FROM tech_artifact_ext WHERE bool_delete_enum = FALSE AND bool_beforehand_scheduling = TRUE GROUP BY artifact_id ) t1 ON t1.artifact_id = ta.id LEFT JOIN plan_area pa ON pa.bool_delete_enum = FALSE AND pa.id = ta.area_id WHERE ta.bool_delete_enum = FALSE AND (ta.quantity - IFNULL(t1.quantity, 0)) > 0
AND ta.project_id = #{projectId}
AND ta.monomer_id = #{monomerId}
AND ta.area_id = #{areaId}
AND ta.structure_class_id = #{artifactClassId}
AND (ta.name LIKE #{artifactNoOrNameLike} OR ta.serial_number LIKE #{artifactNoOrNameLike})
